        Cursor cursor = ctx.getContentResolver().query(uri, new String[]{"_id", "_data"}, "_data=?", new String[]{path}, null);
        if (cursor != null) {
            if (cursor.moveToFirst() && cursor.getCount() > 0) {
                String _id = cursor.getString(0);
                ctx.getContentResolver().update(uri, cv, "_data=?", new String[]{path});
                newUri = ContentUris.withAppendedId(uri, Long.valueOf(_id).longValue());
            } else {
                cv.put("_data", path);
                cv.put("title", name);
                cv.put("mime_type", "audio/mp3");
                newUri = ctx.getContentResolver().insert(uri, cv);
            }
            switch (id) {
                case 0:
                    RingtoneManager.setActualDefaultRingtoneUri(ctx, 1, newUri);
                    break;
                case 1:
                    RingtoneManager.setActualDefaultRingtoneUri(ctx, 2, newUri);
                    break;
                case 2:
                    RingtoneManager.setActualDefaultRingtoneUri(ctx, 4, newUri);
                    break;
                case 3:
                    RingtoneManager.setActualDefaultRingtoneUri(ctx, 7, newUri);
                    break;
            }
        }
    }

