package com.lu.classicringtones;

public class PlayService extends Service {
    public static boolean isPlaying = false;
    public static boolean isPause = true;
    public static boolean isReleased = false;
    public static MediaPlayer mp3Player = null;

    @Override // android.app.Service
    public IBinder onBind(Intent arg0) {
        return null;
    }

    @Override // android.app.Service
    public int onStartCommand(Intent intent, int flags, int startId) {
        try {
            int MSG = intent.getIntExtra("MSG", 0);
            if (AppConstant.MP3INFO.mp3info != null) {
                if (MSG == 1) {
                    start(AppConstant.MP3INFO.mp3info);
                }
                if (MSG == 2) {
                    pause();
                }
                if (MSG == 3) {
                    stop();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return super.onStartCommand(intent, flags, startId);
    }

    private void start(Mp3Info mp3info) {
        stop();
        try {
            AssetFileDescriptor afd = getAssets().openFd("ring/" + mp3info.getMp3Name());
            mp3Player = new MediaPlayer();
            mp3Player.setDataSource(afd.getFileDescriptor(), afd.getStartOffset(), afd.getLength());
            mp3Player.setLooping(true);
            mp3Player.prepare();
            mp3Player.start();
            isPlaying = true;
            isReleased = false;
            isPause = false;
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void pause() {
        if (mp3Player != null) {
            if (!isReleased) {
                if (!isPause) {
                    mp3Player.pause();
                    isPause = true;
                    return;
                } else {
                    mp3Player.start();
                    isPause = false;
                    return;
                }
            }
            return;
        }
        start(AppConstant.MP3INFO.mp3info);
    }

    private void stop() {
        if (mp3Player != null && isPlaying) {
            if (!isReleased) {
                mp3Player.stop();
                mp3Player.release();
                isReleased = true;
            }
            isPlaying = false;
        }
    }
}

